import { KeystoneContext } from "@keystone-6/core/types";
import {
  USER_AUTH_LOG_SOURCE,
  USER_AUTH_LOG_STEP,
} from "../../../../models/User/UserAuthLog/constants";
import { writeUserAuthLog } from "../../../../utils/auth/userAuthLogWrite";
import {
  SIGNUP_ROLE_NAMES,
  findSignupRoleIds,
} from "../../../../utils/auth/signupRoles";
import { PRODUCT } from "../../../../utils/constants/product";
import { provisionSignupCompany } from "../../../../utils/access/provisionSignupCompany";
import { cleanAttribution } from "../../../../utils/analytics/attribution";

/** Campos de `data` que acepta el registro. `product` lo pone el servidor. */
const REGISTER_ALLOWED_FIELDS: ReadonlySet<string> = new Set([
  "name",
  "lastName",
  "secondLastName",
  "username",
  "email",
  "password",
  "phone",
]);

const typeDefs = ``;

const definition = `
  registerUser(data: UserCreateInput!, referrerCode: String, companyName: String, attribution: JSON): User
`;

const resolver = {
  registerUser: async (
    _root: unknown,
    {
      data,
      referrerCode,
      companyName,
      attribution,
    }: {
      data: Record<string, unknown>;
      referrerCode?: string | null;
      companyName?: string | null;
      attribution?: unknown;
    },
    context: KeystoneContext,
  ) => {
    const startedAt = Date.now();
    const emailStr = String(data?.email ?? "").trim();
    // Solo datos personales. Lo demás de UserCreateInput (prueba interna, permisos, espacios,
    // suspensión, roles, empresa…) se ignora: la mutación crea con sudo y no debe dejar que quien
    // se registra se los ponga.
    const safeUserData = Object.fromEntries(
      Object.entries(data ?? {}).filter(([key]) => REGISTER_ALLOWED_FIELDS.has(key)),
    );

    let referredByConnect: { connect: { id: string } } | undefined;

    if (referrerCode) {
      const referrer = await context.sudo().query.User.findOne({
        where: { referralCode: referrerCode.toUpperCase() },
        query: "id",
      });

      if (!referrer) {
        await writeUserAuthLog(context, {
          startedAt,
          source: USER_AUTH_LOG_SOURCE.REGISTER_USER,
          step: USER_AUTH_LOG_STEP.REGISTER_FAIL_INVALID_REFERRER,
          success: false,
          message: "El código de referido no pertenece a ningún usuario.",
          email: emailStr,
          userId: null,
          responseSnapshot: {
            referrerCode: referrerCode.toUpperCase(),
          },
        });
        throw new Error("El código de referido no pertenece a ningún usuario.");
      }

      referredByConnect = { connect: { id: referrer.id } };
    }

    try {
      const trimmedCompanyName = companyName?.trim() ?? "";
      let companyId: string | undefined;

      const signupRoleIds = await findSignupRoleIds(context);
      if (signupRoleIds.length !== SIGNUP_ROLE_NAMES.length) {
        throw new Error(
          "No se pudieron asignar los roles de empresa. Contacta a soporte.",
        );
      }

      const user = await context.sudo().query.User.createOne({
        data: {
          ...safeUserData,
          // Este registro es el de Kadesh Negocios: define la marca de sus correos.
          product: PRODUCT.SAAS,
          referredBy: referredByConnect,
          roles: { connect: signupRoleIds.map((id) => ({ id })) },
          signupAttribution: cleanAttribution(attribution) ?? undefined,
        },
        query:
          "id name lastName secondLastName email phone username referralCode referredBy { id }",
      });

      if (trimmedCompanyName) {
        companyId = await provisionSignupCompany(
          context,
          (user as { id: string }).id,
          trimmedCompanyName,
        );
      }

      await writeUserAuthLog(context, {
        startedAt,
        source: USER_AUTH_LOG_SOURCE.REGISTER_USER,
        step: USER_AUTH_LOG_STEP.REGISTER_SUCCESS,
        success: true,
        message: "Usuario registrado correctamente.",
        email: emailStr,
        userId: (user as { id: string }).id,
        responseSnapshot: {
          userId: (user as { id: string }).id,
          companyId: companyId ?? null,
          referrerCode: referrerCode
            ? String(referrerCode).toUpperCase()
            : null,
        },
      });

      return user;
    } catch (e: unknown) {
      const message =
        e instanceof Error ? e.message : "Error al registrar el usuario.";
      await writeUserAuthLog(context, {
        startedAt,
        source: USER_AUTH_LOG_SOURCE.REGISTER_USER,
        step: USER_AUTH_LOG_STEP.REGISTER_FAIL,
        success: false,
        message,
        email: emailStr,
        userId: null,
        responseSnapshot: {
          errorName: e instanceof Error ? e.name : "unknown",
        },
      });
      throw e;
    }
  },
};

export default { typeDefs, definition, resolver };
